    """
    Implements a backtracking regex matching algorithm to support literal characters,
    '.', '*', and '+' operators for basic regex matching.
    """

    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
