def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching algorithm using recursion and memoization.
    Supports literals, '.', '*', and '+'.
    """
    memo = {}

    def dp(p_index: int, t_index: int) -> bool:
        if (p_index, t_index) in memo:
            return memo[(p_index, t_index)]

        if p_index == len(pattern):
            result = t_index == len(text)
        else:
            first_match = (t_index < len(text)) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.')

            if p_index + 1 < len(pattern) and pattern[p_index + 1] in '*+':
                if pattern[p_index + 1] == '*':
                    result = dp(p_index + 2, t_index) or (first_match and dp(p_index, t_index + 1))
                elif pattern[p_index + 1] == '+':
                    result = first_match and (dp(p_index, t_index + 1) or dp(p_index + 2, t_index))
            else:
                result = first_match and dp(p_index + 1, t_index + 1)

        memo[(p_index, t_index)] = result
        return result

    return dp(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for basic regex matching
    that supports literal characters, '.', '*', and '+'.
    """

    def match_helper(p: str, t: str) -> bool:
        if not p:
            return not t

        first_match = bool(t) and (p[0] == t[0] or p[0] == '.')

        if len(p) >= 2 and p[1] in {'*', '+'}:
            if p[1] == '*':
                return (match_helper(p[2:], t) or
                        (first_match and match_helper(p, t[1:])))
            elif p[1] == '+':
                return first_match and (match_helper(p, t[1:]) or match_helper(p[2:], t))

        return first_match and match_helper(p[1:], t[1:])

    return match_helper(pattern, text)
